    --surface-hover: #2a2a2a;
    --text-color: #e0e0e0;
    --text-muted: #aaaaaa;
    --accent-color: #3b82f6;
    --border-color: #333333;
    --focus-ring: 0 0 0 2px var(--bg-color), 0 0 0 4px var(--accent-color);
}

body {
    background-color: var(--bg-color);
    color: var(--text-color);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
    margin: 0;
    padding: 2rem 1rem;
    display: flex;
    justify-content: center;
}

main {
    max-width: 800px;
    width: 100%;
}

h1 {
    font-size: 2.5rem;
    margin-bottom: 2rem;
    text-align: center;
    color: #ffffff;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.2s;
    text-decoration: none;
    border-radius: 0 0 4px 0;
}

.skip-link:focus {
    top: 0;
}

.example {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    margin-bottom: 1rem;
    overflow: hidden;
    transition: background-color 0.2s ease;
}

.example:hover {
    background-color: var(--surface-hover);
}

.disclosure-trigger {
    width: 100%;
    background: none;
    border: none;
    color: inherit;
    font: inherit;
    font-size: 1.25rem;
    font-weight: 600;
    text-align: left;
    padding: 1.5rem;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    outline: none;
}

.disclosure-trigger:focus-visible {
    box-shadow: inset 0 0 0 2px var(--accent-color);
}

.disclosure-trigger .icon {
    width: 20px;
    height: 20px;
    transition: transform 0.3s ease;
}

.disclosure-trigger[aria-expanded="true"] .icon {
    transform: rotate(180deg);
}

.details {
    padding: 0 1.5rem 1.5rem 1.5rem;
    color: var(--text-muted);
}

.details[hidden] {
    display: none;
}

/* Forced Colors Mode */
@media (forced-colors: active) {
    .example {
        border: 1px solid ButtonBorder;
    }
    .disclosure-trigger:focus-visible {
        outline: 2px solid Highlight;
    }
}
